solution.solution.rs:
#[derive(Debug, Clone, Copy, PartialEq)]
enum Direction { North, East, South, West }

#[derive(Debug, Clone, Copy, PartialEq)]
enum Turn { Left, Right }

#[derive(Debug, Clone, PartialEq)]
enum Command { Forward(u32), Turn(Turn), Say(String) }

#[derive(Debug)]
struct Robot { x: i32, y: i32, facing: Direction, log: Vec<String> }

impl Direction {
    fn turned(self, turn: Turn) -> Direction {
        match (self, turn) {
            (Direction::North, Turn::Right) | (Direction::South, Turn::Left) => Direction::East,
            (Direction::East, Turn::Right) | (Direction::West, Turn::Left) => Direction::South,
            (Direction::South, Turn::Right) | (Direction::North, Turn::Left) => Direction::West,
            (Direction::West, Turn::Right) | (Direction::East, Turn::Left) => Direction::North,
        }
    }
}

fn parse_command(line: &str) -> Option<Command> {
    let line = line.trim();
    let (word, rest) = match line.split_once(char::is_whitespace) {
        Some((w, r)) => (w, r.trim()),
        None => (line, ""),
    };
    let lower = word.to_lowercase();
    let word: &str = &lower;
    match (word, rest) {
        ("forward", n) => n.parse().ok().map(|n| Command::Forward(n)),
        ("left", "") => Some(Command::Turn(Turn::Left)),
        ("right", "") => Some(Command::Turn(Turn::Right)),
        ("say", text) if !text.is_empty() => Some(Command::Say(text.to_string())),
        _ => None,
    }
}

impl Robot {
    fn new() -> Robot {
        Robot { x: 0, y: 0, facing: Direction::North, log: Vec::new() }
    }

    fn apply(&mut self, command: &Command) {
        match command {
            Command::Forward(n) => {
                let n = *n as i32;
                match self.facing {
                    Direction::North => self.y += n,
                    Direction::East => self.x += n,
                    Direction::South => self.y -= n,
                    Direction::West => self.x -= n,
                }
            }
            Command::Turn(t) => self.facing = self.facing.turned(*t),
            Command::Say(text) => self.log.push(format!("({}, {}) {}", self.x, self.y, text)),
        }
    }
}

unitTests:
test("parsing commands", || {
    check_eq(parse_command("forward 3"), Some(Command::Forward(3)));
    check_eq(parse_command("  FORWARD   12 "), Some(Command::Forward(12)));
    check_eq(parse_command("Left"), Some(Command::Turn(Turn::Left)));
    check_eq(parse_command("say  hello there "), Some(Command::Say("hello there".to_string())));
    check_eq(parse_command("forward -1"), None);
    check_eq(parse_command("forward"), None);
    check_eq(parse_command("say"), None);
    check_eq(parse_command("left now"), None);
    check_eq(parse_command("jump"), None);
});

test("driving", || {
    let mut r = Robot::new();
    for line in ["forward 2", "right", "forward 3", "say hi", "right", "right", "right", "forward 1", "left", "left", "forward 5"] {
        r.apply(&parse_command(line).unwrap());
    }
    check_eq((r.x, r.y, r.facing), (3, -2, Direction::South));
    check_eq(r.log, vec!["(3, 2) hi"]);
});

test("turning all the way round", || {
    let mut r = Robot::new();
    for _ in 0..4 {
        r.apply(&Command::Turn(Turn::Left));
    }
    check_eq(r.facing, Direction::North);
});

